mapper.select:
select concat(grouped.target_batch, '_', grouped.target_id) as targetId, grouped.timestampBegin, grouped.timestampEnd, timestampdiff(second, grouped.timestampBegin, grouped.timestampEnd) as duration, grouped.recordCount from ( select drt.target_batch, drt.target_id, min(drt.timestamp) as timestampBegin, max(drt.timestamp) as timestampEnd, count(1) as recordCount from data_radar_target drt where drt.target_batch is not null and drt.target_id is not null and (drt.is_delete = 0 or drt.is_delete is null) and drt.timestamp >= #{startDateTime} and drt.timestamp < #{endDateTime}
and drt.target_type = #{targetType}
group by drt.target_batch, drt.target_id ) grouped order by grouped.timestampEnd desc
